function raycastTerrain(ray, out) {
  // Binary-search along ray where ray.y crosses sampleHeight(x,z)
  let tLo = 0.2, tHi = Math.max(landRadius * 2.5, 280);
  const o = ray.origin, d = ray.direction;
  // Expand until below ground or max
  let found = false;
  for (let expand = 0; expand < 8; expand++) {
    const px = o.x + d.x * tHi;
    const py = o.y + d.y * tHi;
    const pz = o.z + d.z * tHi;
    if (py <= sampleHeight(px, pz) + 0.05) { found = true; break; }
    tHi *= 1.6;
    if (tHi > 900) break;
  }
  if (!found) {
    // Fallback: horizontal plane at player ground height
    const gh = sampleHeight(player.position.x, player.position.z);
    if (Math.abs(d.y) < 1e-5) return false;
    const t = (gh - o.y) / d.y;
    if (t < 0.1) return false;
    out.set(o.x + d.x * t, gh, o.z + d.z * t);
    return true;
  }
  for (let i = 0; i < 20; i++) {
    const tm = (tLo + tHi) * 0.5;
    const px = o.x + d.x * tm;
    const py = o.y + d.y * tm;
    const pz = o.z + d.z * tm;
    if (py > sampleHeight(px, pz)) tLo = tm;
    else tHi = tm;
  }
  const tHit = (tLo + tHi) * 0.5;
  const hx = o.x + d.x * tHit;
  const hz = o.z + d.z * tHit;
  out.set(hx, sampleHeight(hx, hz), hz);
  return true;
}

function shotBlocked(from, to) {
  const dx = to.x - from.x, dy = to.y - from.y, dz = to.z - from.z;
  const flat = Math.hypot(dx, dz);
  if (flat < 0.4) return false;
  // Terrain: step along the line and see whether the ground climbs above it. The
  // tolerance keeps a shot that grazes a slope from reading as blocked.
  const steps = Math.min(40, Math.max(5, Math.ceil(flat / 1.5)));
  for (let i = 1; i < steps; i++) {
    const u = i / steps;
    if (from.y + dy * u < sampleHeight(from.x + dx * u, from.z + dz * u) - 0.25) return true;
  }
  if (house.present) {
    const hy0 = house.group.position.y, hh = HQ_H;
    if (segmentHitsBox(from.x, from.y, from.z, to.x, to.y, to.z,
      house.group.position.x, hy0 + hh / 2, house.group.position.z, house.half, hh / 2, house.half) !== null) return true;
  }
  const segMinX = Math.min(from.x, to.x), segMaxX = Math.max(from.x, to.x);
  const segMinZ = Math.min(from.z, to.z), segMaxZ = Math.max(from.z, to.z);
  for (const rock of rocks) {
    if (!rock.alive || !rock.mesh.visible) continue;
    if (rock.x + rock.radius < segMinX || rock.x - rock.radius > segMaxX ||
        rock.z + rock.radius < segMinZ || rock.z - rock.radius > segMaxZ) continue;
    const ry = rock.mesh.position.y;
    if (segmentHitsCylinder(from.x, from.y, from.z, to.x, to.y, to.z,
        rock.x, rock.z, rock.radius, ry, ry + rock.height) !== null) return true;
  }
  for (const t of trees) {
    const tr = (t.canopyRadius || t.trunkRadius) + 0.4;
    if (t.x + tr < segMinX || t.x - tr > segMaxX || t.z + tr < segMinZ || t.z - tr > segMaxZ) continue;
    if (t.stump && t.stumpMesh) {
      const baseY = t.stumpMesh.position.y;
      if (segmentHitsCylinder(from.x, from.y, from.z, to.x, to.y, to.z,
          t.x, t.z, t.trunkRadius + 0.15, baseY, baseY + 0.55) !== null) return true;
      continue;
    }
    if (!t.alive || t.falling) continue;
    const baseY = t.group.position.y;
    if (t.leafHealth > 0 && segmentHitsCylinder(from.x, from.y, from.z, to.x, to.y, to.z,
        t.x, t.z, t.canopyRadius * 0.9, baseY + t.canopyBottom * 0.65, baseY + t.canopyTop) !== null) return true;
    if (segmentHitsCylinder(from.x, from.y, from.z, to.x, to.y, to.z,
        t.x, t.z, t.trunkRadius + 0.12, baseY, baseY + t.canopyBottom + 0.4) !== null) return true;
  }
  // GB-58: the line also sees what else stops his rounds - his own pieces (bar the railings
  // and wire his rounds pass through) and the landmark solids. A spider behind his wall read a
  // clear line, held its distance and spat, and every round went into the wall. A hit in the
  // last 0.3 m is the thing aimed at, not something in the way.
  const lineLen = Math.hypot(dx, dy, dz), nearEnd = 1 - 0.3 / Math.max(0.3, lineLen);
  for (const b of builds) {
    if (b.hp <= 0 || !b.mesh || b.type === 'railing' || b.type === 'wire') continue;
    const r = (isEdgeKind(b.type) ? BUILD_GRID * 0.75 : (b.radius || 0.6)) + 0.1;
    if (b.x + r < segMinX || b.x - r > segMaxX || b.z + r < segMinZ || b.z - r > segMaxZ) continue;
    const h = segmentHitsBuild(b, from.x, from.y, from.z, to.x, to.y, to.z);
    if (h !== null && h < nearEnd) return true;
  }
  for (const ws of worldSolids) {
    if (ws.x + ws.radius < segMinX || ws.x - ws.radius > segMaxX ||
        ws.z + ws.radius < segMinZ || ws.z - ws.radius > segMaxZ) continue;
    const h = segmentHitsCylinder(from.x, from.y, from.z, to.x, to.y, to.z, ws.x, ws.z, ws.radius, ws.y0, ws.y1);
    if (h !== null && h < nearEnd) return true;
  }
  return false;
}

function updateMouseAim(dt) {
  if (!pointerOnCanvas) return;
  // CL-50 (Jerry): while a cinematic has the camera, the cursor's ground point swings with
  // it; the marine keeps the facing he had (no 360 on the last kill).
  if (waveFinisher || loopCine) return;
  // Keep the last sight line while lowering. Raycasting through a camera still
  // inside its zoom transition otherwise swings the rifle and camera together.
  if (!sniperScopingNow && scopeAmt > 0.002) return;
  const scoped = updateScopeDir(dt);
  if (scoped) {
    // The ray runs down the scope's own line from the muzzle, which is where the
    // bullet leaves: what sits under the crosshair is what gets hit.
    aimRaycaster.ray.origin.copy(getMuzzleWorld());
    aimRaycaster.ray.direction.copy(scopeDir);
  } else {
    _scopedNdc.set(aimPointerNdc.x, aimPointerNdc.y);
    aimRaycaster.setFromCamera(_scopedNdc, camera);
  }
  const ray = aimRaycaster.ray;
  // Terrain first; a cursor above the skyline used to hit nothing and freeze the
  // aim, so it now aims at a far point along the ray instead.
  let groundT = Infinity;
  if (raycastTerrain(ray, aimHit)) groundT = aimHit.distanceTo(ray.origin);
  aimGroundDist = groundT;
  // Then any zombie in front of that: the reticle over a body aims at the body, not
  // the ground behind it. Same cylinders the bullets use (see updateProjectiles).
  const zt = rayPickZombie(ray, groundT);
  if (zt !== Infinity) aimHit.copy(ray.origin).addScaledVector(ray.direction, zt);
  else if (groundT === Infinity) aimHit.copy(ray.origin).addScaledVector(ray.direction, AIM_SKY_DIST);
  aimTarget.copy(aimHit);
  updateShotLos(zt !== Infinity);
  // GB-50: a stumble throws the aim off a little, easing back over HIT_AIM_S.
  if (hitStumble.aimT > 0 && hitStumble.aimOff) {
    const off = hitStumble.aimOff * Math.pow(hitStumble.aimT / HIT_AIM_S, 2);
    const ox = aimTarget.x - player.position.x, oz = aimTarget.z - player.position.z;
    const c = Math.cos(off), s = Math.sin(off);
    aimTarget.x = player.position.x + ox * c + oz * s;
    aimTarget.z = player.position.z - ox * s + oz * c;
  }
  const dx = aimTarget.x - player.position.x;
  const dz = aimTarget.z - player.position.z;
  if (dx * dx + dz * dz < 0.04) return;
  // Snap — preferred for TPS mouse aim (less wonky lag)
  aimYaw = Math.atan2(dx, dz);
}

function trainingRound(p) {
  const tg = training.tg;
  if (!tg) return false;
  _trA.x = p.prev.x; _trA.y = p.prev.y; _trA.z = p.prev.z; _trB.x = p.pos.x; _trB.y = p.pos.y; _trB.z = p.pos.z;
  let best = null, bt = 2;
  for (const s of tg.solids) {
    if (s.target != null && tg.targets[s.target].state !== 'up') continue;
    const t = segmentBox(_trA, _trB, s);
    if (t !== null && t < bt) { bt = t; best = s; }
  }
  if (!best) return false;
  for (const z of zombies) {
    if (!z.alive) continue;
    const zy = z.mesh.position.y;
    const t = segmentHitsCylinder(_trA.x, _trA.y, _trA.z, _trB.x, _trB.y, _trB.z, z.mesh.position.x, z.mesh.position.z, z.radius + 0.1, zy, zy + (z.hitH || 1.45));
    if (t !== null && t <= bt) return false;
  }
  const hx = _trA.x + (_trB.x - _trA.x) * bt, hy = _trA.y + (_trB.y - _trA.y) * bt, hz = _trA.z + (_trB.z - _trA.z) * bt;
  if (best.target != null) {
    if (tg.hitTarget(best.target)) {
      training.hits++;
      spawnEmbers(hx, hy, hz, 6, 0.6);
      AudioSys.armorHit && AudioSys.armorHit(true);
      publishUI('training-target', { lane: best.target + 1, range: tg.targets[best.target].range, hits: training.hits });
    }
  } else spawnDust(hx, hy, hz, 2);
  p.hit = true;
  return true;
}
